            float4 a_val = reinterpret_cast<const float4*>(A + row * N + tile_col)[0];
            sA[threadIdx.y][threadIdx.x] = a_val.x;
            sA[threadIdx.y][threadIdx.x + 1] = a_val.y;
            sA[threadIdx.y][threadIdx.x + 2] = a_val.z;
